INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist E-Procurement dasselbe wie E-Commerce?', 2, '[{"text": "Nein", "correct": true, "because": "B2B-Fokus vs. allgemeiner Handel"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt E-Procurement?', 3, '[{"text": "Automatisierung der Beschaffung", "correct": true, "because": "Effizienz steigern"}, {"text": "Daten speichern", "correct": false, "because": "Sekundär"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu E-Procurement?', 5, '[{"text": "E-Tendering", "correct": true, "because": "Ausschreibungen digital"}, {"text": "E-Auctioning", "correct": true, "because": "Auktionen online"}, {"text": "Papierkataloge", "correct": false, "because": "Digitaler Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) E-Procurement reduziert manuelle Prozesse. b) Es ist nur für große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Größen nutzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei E-Procurement?', 4, '[{"text": "Digitale Plattform", "correct": false, "because": "Grundlage"}, {"text": "Lieferantenmanagement", "correct": false, "because": "Zentral"}, {"text": "Papierformate", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob E-Procurement immer eine Internetverbindung braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Online-Prozess"}, {"text": "Nein", "correct": false, "because": "Internet nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für E-Procurement genutzt?', 3, '[{"text": "ERP-System", "correct": true, "because": "Integration"}, {"text": "Texteditor", "correct": false, "because": "Nicht relevant"}, {"text": "Browser", "correct": false, "because": "Zu allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet E-Procurement?', 5, '[{"text": "Kostensenkung", "correct": true, "because": "Automatisierung"}, {"text": "Transparenz", "correct": true, "because": "Datenverfolgung"}, {"text": "Papierverbrauch", "correct": false, "because": "Reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) E-Procurement verbessert die Effizienz. b) Es ist nur für den öffentlichen Sektor. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Sektoren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für E-Procurement?', 4, '[{"text": "Internetverbindung", "correct": false, "because": "Online nötig"}, {"text": "E-Procurement-Software", "correct": false, "because": "Grundlage"}, {"text": "Physische Kataloge", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist E-Procurement nur für B2B?', 2, '[{"text": "Nein", "correct": true, "because": "Auch B2G"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse umfasst E-Procurement?', 4, '[{"text": "Bestellung", "correct": true, "because": "Kaufprozess"}, {"text": "Rechnungsstellung", "correct": true, "because": "Abrechnung"}, {"text": "Papierbearbeitung", "correct": false, "because": "Digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass E-Procurement keine Sicherheitsmaßnahmen braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "VPN, Verschlüsselung nötig"}, {"text": "Ja", "correct": false, "because": "Sicherheit zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei E-Procurement?', 3, '[{"text": "Effizienz", "correct": true, "because": "Prozessoptimierung"}, {"text": "Papierkataloge", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) E-Procurement nutzt digitale Plattformen. b) Es ist nur für kleine Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen E-Procurement?', 5, '[{"text": "EDI", "correct": true, "because": "Datenintegration"}, {"text": "VPN", "correct": true, "because": "Sichere Verbindung"}, {"text": "Papierfax", "correct": false, "because": "Analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei E-Procurement unwichtig?', 3, '[{"text": "Automatisierung", "correct": false, "because": "Zentral"}, {"text": "Transparenz", "correct": false, "because": "Vorteil"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann E-Procurement Lieferketten optimieren?', 3, '[{"text": "Ja", "correct": true, "because": "Effizienz steigern"}, {"text": "Nein", "correct": false, "because": "Optimierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob E-Procurement Kosten senkt?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisierung spart"}, {"text": "Nein", "correct": false, "because": "Kostensenkung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für E-Procurement zentral?', 4, '[{"text": "Digitale Automatisierung", "correct": true, "because": "Kernprinzip"}, {"text": "Papierprozesse", "correct": false, "because": "Vermeiden"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisiert"}]');
